// Generates the icon packages from icons/: React and Vue components (animated and /static)
// and the raw SVG package. Generated files are git-ignored; edit icons/ and the templates here.
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { checkIcon, PAINTED_VARIANTS, type IconMeta, type Variant } from "./lib/icon-rules.ts";
import { baseCss, drawnParts, iconCss, type Motion, type ToggleMotion } from "./lib/motion.ts";
import { parseSvgTree, serializeSvg, withoutParts, type SvgNode } from "./lib/svg-tree.ts";

const root = join(import.meta.dirname, "..");
const iconsDir = join(root, "icons");
const svgOut = join(root, "packages", "svg");

interface IconVariant {
  /** Source icon name, e.g. "heart". */
  name: string;
  variant: Variant;
  /** Kebab id of this component, e.g. "heart-filled". Used for CSS classes and file names. */
  id: string;
  /** Exported component name, e.g. "HeartFilled". */
  component: string;
  meta: IconMeta;
  nodes: SvgNode[];
  /** Parts drawn only in the active state; empty unless the icon has a toggle. */
  activeOnly: string[];
  /** Motion of this variant (a filled or half variant may override the outline's). */
  motion: Motion[];
  /** How toggle parts change when active; shared by all variants. */
  toggleMotion: ToggleMotion[];
  toggle: boolean;
}

const pascal = (id: string) =>
  id
    .split("-")
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join("");

function loadIcons(): IconVariant[] {
  const names = readdirSync(iconsDir)
    .filter((f) => f.endsWith(".svg"))
    .map((f) => f.slice(0, -4))
    .sort();
  const out: IconVariant[] = [];
  const problems: string[] = [];
  for (const name of names) {
    const meta = JSON.parse(readFileSync(join(iconsDir, `${name}.json`), "utf8")) as IconMeta;
    for (const variant of ["outline", ...PAINTED_VARIANTS] as const) {
      const file = join(iconsDir, variant === "outline" ? "" : variant, `${name}.svg`);
      if (!existsSync(file)) continue;
      const svg = readFileSync(file, "utf8");
      const errors = checkIcon(name, svg, meta, variant);
      if (errors.length) problems.push(`${variant}/${name}: ${errors.join("; ")}`);
      const id = variant === "outline" ? name : `${name}-${variant}`;
      out.push({
        name,
        variant,
        id,
        component: pascal(id),
        meta,
        nodes: parseSvgTree(svg),
        activeOnly: meta.toggle?.activeOnly ?? [],
        motion:
          ((variant === "outline" ? undefined : meta[variant]?.animation) ?? meta.animation)
            .motion ?? [],
        toggleMotion: meta.toggle?.motion ?? [],
        toggle: meta.toggle !== undefined,
      });
    }
  }
  if (problems.length) {
    throw new Error(
      `Icons break the drawing rules (run pnpm check:icons):\n${problems.join("\n")}`,
    );
  }
  return out;
}

/** A framework package the components are generated into. */
interface Target {
  out: string;
  /** SVG attribute names the framework spells differently. */
  attrNames: Record<string, string>;
}

const TARGETS: Target[] = [
  {
    out: join(root, "packages", "react", "src", "generated"),
    attrNames: { "fill-rule": "fillRule" },
  },
  { out: join(root, "packages", "vue", "src", "generated"), attrNames: {} },
];

function nodeCode(nodes: SvgNode[], target: Target): string {
  const items = nodes.map((n) => {
    const attrs = Object.fromEntries(
      Object.entries(n.attrs).map(([k, v]) => [target.attrNames[k] ?? k, v]),
    );
    const children = n.children.length ? `, ${nodeCode(n.children, target)}` : "";
    return `[${JSON.stringify(n.tag)}, ${JSON.stringify(attrs)}${children}]`;
  });
  return `[${items.join(", ")}]`;
}

/** The `d` of every part that is a single path. */
function partPaths(nodes: SvgNode[], out: Record<string, string> = {}): Record<string, string> {
  for (const n of nodes) {
    const part = n.attrs["data-part"];
    if (part && n.tag === "path" && n.attrs.d) out[part] = n.attrs.d;
    partPaths(n.children, out);
  }
  return out;
}

const css = (icon: IconVariant) =>
  iconCss(icon.id, icon.motion, icon.activeOnly, icon.toggleMotion, partPaths(icon.nodes));

const SHAPES = new Set(["path", "line", "polyline", "polygon", "circle", "ellipse", "rect"]);

/** Gives every shape inside a drawn part pathLength="1", so the draw preset needs no lengths. */
function withPathLength(nodes: SvgNode[], parts: ReadonlySet<string>, inside = false): SvgNode[] {
  return nodes.map((n) => {
    const drawn = inside || parts.has(n.attrs["data-part"] ?? "");
    const attrs = drawn && SHAPES.has(n.tag) ? { ...n.attrs, pathLength: "1" } : n.attrs;
    return { ...n, attrs, children: withPathLength(n.children, parts, drawn) };
  });
}

const header = (icon: IconVariant) => {
  const source = icon.variant === "outline" ? icon.name : `${icon.variant}/${icon.name}`;
  return `// Generated by scripts/build-icons.ts from icons/${source}.svg. Do not edit.\n`;
};

function animatedModule(icon: IconVariant, target: Target): string {
  const factory = icon.toggle ? "createToggleIcon" : "createIcon";
  const type = icon.toggle ? "ToggleIconComponent" : "IconComponent";
  const styles = css(icon);
  const nodes = withPathLength(icon.nodes, new Set(drawnParts(icon.motion, icon.toggleMotion)));
  const args = [JSON.stringify(icon.id), JSON.stringify(icon.component), nodeCode(nodes, target)];
  if (styles) args.push(JSON.stringify(styles));
  return `${header(icon)}import { ${factory} } from "../../lib/create-icon";
import type { ${type} } from "../../lib/types";

// Pure, so bundlers drop icons that are not imported. The explicit type keeps .d.ts small.
export const ${icon.component}: ${type} = /* @__PURE__ */ ${factory}(${args.join(", ")});
`;
}

/** The drawing at rest: without parts shown only when active. */
const restingNodes = (icon: IconVariant) => withoutParts(icon.nodes, new Set(icon.activeOnly));

function staticModule(icon: IconVariant, target: Target): string {
  const nodes = restingNodes(icon);
  return `${header(icon)}import { createStaticIcon } from "../../lib/create-static-icon";
import type { StaticIconComponent } from "../../lib/types";

export const ${icon.component}: StaticIconComponent = /* @__PURE__ */ createStaticIcon(${JSON.stringify(icon.id)}, ${JSON.stringify(icon.component)}, ${nodeCode(nodes, target)});
`;
}

function write(file: string, content: string) {
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, content);
}

function buildPackage(icons: IconVariant[], target: Target) {
  const out = target.out;
  rmSync(out, { recursive: true, force: true });
  const index: string[] = [];
  const staticIndex: string[] = [];
  for (const icon of icons) {
    write(join(out, "icons", `${icon.id}.ts`), animatedModule(icon, target));
    write(join(out, "static", `${icon.id}.ts`), staticModule(icon, target));
    index.push(`export { ${icon.component} } from "./icons/${icon.id}";`);
    staticIndex.push(`export { ${icon.component} } from "./static/${icon.id}";`);
  }
  const note = "// Generated by scripts/build-icons.ts. Do not edit.\n";
  write(join(out, "index.ts"), `${note}${index.join("\n")}\n`);
  write(
    join(out, "base-css.ts"),
    `${note}// Shared motion CSS, loaded once per page by every animated icon.\nexport const BASE_CSS = ${JSON.stringify(baseCss())};\n`,
  );
  write(join(out, "static.ts"), `${note}${staticIndex.join("\n")}\n`);
}

function buildSvg(icons: IconVariant[]) {
  for (const dir of ["icons", "icons.json"])
    rmSync(join(svgOut, dir), { recursive: true, force: true });
  for (const icon of icons) {
    const from = join(iconsDir, icon.variant === "outline" ? "" : icon.variant, `${icon.name}.svg`);
    const rootTag = /<svg[^>]*>/.exec(readFileSync(from, "utf8"))?.[0] ?? "<svg>";
    write(join(svgOut, "icons", `${icon.id}.svg`), serializeSvg(rootTag, restingNodes(icon)));
  }
  const outlines = icons.filter((i) => i.variant === "outline");
  const list = outlines.map((icon) => ({
    ...icon.meta,
    component: icon.component,
    variants: icons
      .filter((i) => i.name === icon.name)
      .map((i) => ({ variant: i.variant, id: i.id, component: i.component })),
  }));
  write(join(svgOut, "icons.json"), `${JSON.stringify(list, null, 2)}\n`);
}

/** How much of the described motion and second states already has CSS. */
function coverage(icons: IconVariant[]): string {
  const moving = icons.filter((i) => i.motion.length > 0);
  const toggles = icons.filter((i) => i.toggle);
  const missingToggles = toggles.filter(
    (i) => !(i.meta.toggle?.parts ?? []).every((p) => i.toggleMotion.some((t) => t.part === p)),
  );
  const lines = [
    `Motion CSS: ${moving.length}/${icons.length} components`,
    `Toggle CSS: ${toggles.length - missingToggles.length}/${toggles.length} components` +
      (missingToggles.length ? ` (missing: ${missingToggles.map((i) => i.id).join(", ")})` : ""),
  ];
  return lines.join("\n");
}

const icons = loadIcons();
for (const target of TARGETS) buildPackage(icons, target);
buildSvg(icons);
const outlines = icons.filter((i) => i.variant === "outline").length;
console.log(`Generated ${icons.length} components from ${outlines} icons`);
console.log(coverage(icons));
